#!/usr/bin/env bash
# Regenerates sdk/abi/GaslessTransfer.json and sdk/src/core/abi.ts. Runs INSIDE the toolchain
# container or a configured Linux toolchain. GASLESS_ABI_OUTPUT redirects generated files away from source.
set -euo pipefail
cd "$(dirname "$0")/../.."
contract="${1:-src/GaslessTransfer.sol:GaslessTransfer}"
output="${GASLESS_ABI_OUTPUT:-$PWD}"
# Both files are generated in a scratch directory and moved into place at the end: a failing step leaves the
# existing files as they are instead of a truncated one.
scratch=$(mktemp -d)
trap 'rm -rf -- "$scratch"' EXIT
(cd contracts && forge inspect "$contract" abi --json) | jq '.' > "$scratch/GaslessTransfer.json"
{
  echo '// GENERATED by sdk/scripts/gen-abi.sh; do not edit. Sources: sdk/abi/*.json'
  echo '// (GaslessTransfer: forge inspect; usdc/usdt0: subsets of the Sourcify-verified implementation'
  echo '// ABIs of FiatTokenV2_2 0x235AE97b28466Db30469b89A9fe4cFf0659f82Cb and UChildUSDT0'
  echo '// 0x90040487A6C9F949C4F07CaDCFB0f3B8EEAb4229).'
  for pair in gaslessTransferAbi:GaslessTransfer usdcAbi:usdc usdt0Abi:usdt0; do
    echo
    input="sdk/abi/${pair##*:}.json"
    [[ ${pair##*:} != GaslessTransfer ]] || input="$scratch/GaslessTransfer.json"
    # Assigned first: `set -e` does not see a jq that fails inside the arguments of echo.
    abi=$(jq '.' "$input")
    echo "export const ${pair%%:*} = $abi as const;"
  done
} > "$scratch/abi.ts"
mkdir -p "$output/sdk/abi" "$output/sdk/src/core"
mv "$scratch/GaslessTransfer.json" "$output/sdk/abi/GaslessTransfer.json"
mv "$scratch/abi.ts" "$output/sdk/src/core/abi.ts"
